-- ============================================================
-- eTech Computer Accessories — PostgreSQL / Supabase schema
--
-- Converted from the MySQL (MariaDB) schema in ../01_schema.sql.
-- Run this first, in the Supabase SQL editor or over psql:
--
--     psql "$SUPABASE_DB_URL" -f 01_schema.sql
--
-- Everything lives in the default `public` schema, which is the one
-- Supabase exposes through PostgREST and supabase-js.
--
-- What changed, and why:
--
--   AUTO_INCREMENT   -> GENERATED BY DEFAULT AS IDENTITY. "BY DEFAULT"
--                       rather than "ALWAYS" so the migration can insert
--                       the original ids; 03_sequences.sql then moves the
--                       counters past them.
--   ENUM('a','b')    -> a real CREATE TYPE ... AS ENUM. Same values, same
--                       spelling, so every existing WHERE status='Pending'
--                       still reads the same.
--   TINYINT(1)       -> SMALLINT with a CHECK (0,1), NOT boolean. Keeping
--                       0/1 means WHERE is_active = 1 in the PHP and in the
--                       Flutter client keeps working untouched. Switching
--                       to boolean later is one ALTER per column.
--   TIMESTAMP        -> TIMESTAMPTZ. MySQL stored these as UTC and showed
--   DATETIME            them in Asia/Singapore; the data load pins the
--                       session to +08 so the instants come across intact.
--   ON UPDATE CURRENT_TIMESTAMP
--                    -> MySQL does this in the engine; Postgres needs a
--                       trigger, defined near the bottom of this file.
--   ENGINE=InnoDB    -> dropped. Postgres tables are transactional and
--   utf8mb4             UTF-8 already.
-- ============================================================

BEGIN;

-- ------------------------------------------------------------
-- Drop in dependency order, so the file can be re-run from scratch
-- ------------------------------------------------------------
DROP VIEW  IF EXISTS v_monthly_sales;
DROP VIEW  IF EXISTS v_product_velocity;

DROP TABLE IF EXISTS login_attempts;
DROP TABLE IF EXISTS chatbot_logs;
DROP TABLE IF EXISTS events;
DROP TABLE IF EXISTS wishlist_items;
DROP TABLE IF EXISTS cart_items;
DROP TABLE IF EXISTS order_status_history;
DROP TABLE IF EXISTS order_items;
DROP TABLE IF EXISTS orders;
DROP TABLE IF EXISTS coupons;
DROP TABLE IF EXISTS admins;
DROP TABLE IF EXISTS customers;
DROP TABLE IF EXISTS product_attributes;
DROP TABLE IF EXISTS products;
DROP TABLE IF EXISTS categories;
DROP TABLE IF EXISTS brands;

-- ------------------------------------------------------------
-- Enumerated types
-- ------------------------------------------------------------
DROP TYPE IF EXISTS stock_status;
DROP TYPE IF EXISTS order_status;
DROP TYPE IF EXISTS event_type;

CREATE TYPE stock_status AS ENUM ('in', 'low', 'out');
CREATE TYPE order_status AS ENUM ('Pending', 'Processing', 'Shipped', 'Delivered', 'Cancelled');
CREATE TYPE event_type   AS ENUM ('view', 'cart_add', 'wishlist_add', 'purchase');

-- ------------------------------------------------------------
-- Look-up tables
-- ------------------------------------------------------------

-- Brands (AMD, Asus, MSI, ...). Kept in their own table so the
-- BRANDS menu and the brand filter read from one place.
CREATE TABLE brands (
  brand_id  INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name      VARCHAR(60) NOT NULL UNIQUE
);

-- Categories, with parent_id pointing at another category so a
-- sub-category like "CPU" can sit under "Components".
--
-- NULLS NOT DISTINCT is the one deliberate tightening in this file.
-- MySQL let ('Laptops', NULL) be inserted twice, because a unique index
-- there treats NULLs as different from one another. Postgres does the
-- same by default; NULLS NOT DISTINCT (PG 15+) makes the top-level
-- names genuinely unique, which is what the seed always assumed.
CREATE TABLE categories (
  category_id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name        VARCHAR(60) NOT NULL,
  parent_id   INTEGER NULL REFERENCES categories(category_id) ON DELETE CASCADE,
  CONSTRAINT uq_category UNIQUE NULLS NOT DISTINCT (name, parent_id)
);

-- ------------------------------------------------------------
-- Products
-- ------------------------------------------------------------
CREATE TABLE products (
  product_id   INTEGER PRIMARY KEY,           -- keeps the ids already used by images/<id>.jpg
  name         VARCHAR(200) NOT NULL,
  brand_id     INTEGER NOT NULL REFERENCES brands(brand_id),
  category_id  INTEGER NOT NULL REFERENCES categories(category_id),
  price        NUMERIC(10,2) NOT NULL,        -- what the customer pays

  -- Not recorded yet. Needed for the margin figures and for the
  -- "high-cost stagnant item" test in the dead-stock alerts.
  cost_price   NUMERIC(10,2) NULL,

  -- Real counts aren't recorded yet either, so stock_status is the
  -- field the shop actually uses today. Once stock_qty is filled in,
  -- status should be worked out from it (out at 0, low at or below
  -- reorder_level, otherwise in).
  stock_qty     INTEGER NULL,
  reorder_level INTEGER NOT NULL DEFAULT 5,
  stock_status  stock_status NOT NULL DEFAULT 'in',

  description  TEXT,
  icon         VARCHAR(16),                   -- emoji fallback
  img_slug     VARCHAR(40),                   -- images/<slug>.svg drawing
  image_path   VARCHAR(255) NULL,             -- a real uploaded photo, once there is one

  -- Sold in the shop but never offered in Own Build: legacy boards,
  -- laptop memory, DDR3 repair sticks, surveillance drives.
  exclude_from_builder SMALLINT NOT NULL DEFAULT 0 CHECK (exclude_from_builder IN (0,1)),

  -- soft delete, so old orders keep their product
  is_active    SMALLINT NOT NULL DEFAULT 1 CHECK (is_active IN (0,1)),
  created_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at   TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX idx_product_category ON products (category_id);
CREATE INDEX idx_product_brand    ON products (brand_id);

-- Technical specs. Products differ wildly (a printer has no socket,
-- a CPU has no paper size), so rather than hundreds of mostly-empty
-- columns each spec is a row. A spec that holds several values, like
-- a cooler socket list, is simply several rows with the same key.
CREATE TABLE product_attributes (
  attribute_id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  product_id   INTEGER NOT NULL REFERENCES products(product_id) ON DELETE CASCADE,
  attr_key     VARCHAR(40) NOT NULL,          -- 'socket', 'ramGen', 'wattage', ...
  attr_value   VARCHAR(120) NOT NULL
);

CREATE INDEX idx_attr_lookup  ON product_attributes (attr_key, attr_value);
CREATE INDEX idx_attr_product ON product_attributes (product_id);

-- ------------------------------------------------------------
-- People
-- ------------------------------------------------------------
CREATE TABLE customers (
  customer_id   INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name          VARCHAR(100) NOT NULL,
  email         VARCHAR(120) NOT NULL UNIQUE,
  password_hash VARCHAR(255) NOT NULL,        -- PHP password_hash(), never the raw password
  phone         VARCHAR(30),
  address       TEXT,
  created_at    TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- Shop staff. Separate table so a customer can never become an admin
-- by editing their own row.
CREATE TABLE admins (
  admin_id      INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  username      VARCHAR(60) NOT NULL UNIQUE,
  password_hash VARCHAR(255) NOT NULL,
  name          VARCHAR(100) NOT NULL,
  created_at    TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- ------------------------------------------------------------
-- Promotions
-- ------------------------------------------------------------
-- Creating one of these is what triggers the customer notification.
-- category_id NULL means the coupon applies to everything.
CREATE TABLE coupons (
  coupon_id        INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  code             VARCHAR(30) NOT NULL UNIQUE,
  description      VARCHAR(160),
  category_id      INTEGER NULL REFERENCES categories(category_id) ON DELETE SET NULL,
  discount_percent NUMERIC(5,2) NOT NULL,
  starts_at        TIMESTAMPTZ NOT NULL DEFAULT now(),
  ends_at          TIMESTAMPTZ NULL,
  is_active        SMALLINT NOT NULL DEFAULT 1 CHECK (is_active IN (0,1)),
  created_at       TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- ------------------------------------------------------------
-- Orders
-- ------------------------------------------------------------
CREATE TABLE orders (
  order_id         INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  customer_id      INTEGER NOT NULL REFERENCES customers(customer_id),
  order_date       TIMESTAMPTZ NOT NULL DEFAULT now(),
  status           order_status NOT NULL DEFAULT 'Pending',
  subtotal         NUMERIC(10,2) NOT NULL,
  discount         NUMERIC(10,2) NOT NULL DEFAULT 0,
  total            NUMERIC(10,2) NOT NULL,
  coupon_code      VARCHAR(30) NULL,
  -- copied at checkout so a later profile edit cannot rewrite history
  shipping_name    VARCHAR(100),
  shipping_phone   VARCHAR(30),
  shipping_address TEXT
);

CREATE INDEX idx_order_date   ON orders (order_date);
CREATE INDEX idx_order_status ON orders (status);

-- Name and price are copied in, so an order still reads correctly
-- years later even if the product is renamed, repriced or removed.
CREATE TABLE order_items (
  order_item_id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  order_id      INTEGER NOT NULL REFERENCES orders(order_id) ON DELETE CASCADE,
  -- NULL for a prebuilt bundle
  product_id    INTEGER NULL REFERENCES products(product_id) ON DELETE SET NULL,
  product_name  VARCHAR(200) NOT NULL,
  unit_price    NUMERIC(10,2) NOT NULL,
  unit_cost     NUMERIC(10,2) NULL,           -- cost at the time of sale, for margin
  quantity      INTEGER NOT NULL,
  line_total    NUMERIC(10,2) NOT NULL
);

CREATE INDEX idx_item_product ON order_items (product_id);

-- Every status change, so the admin can see when an order moved on
-- and who moved it.
CREATE TABLE order_status_history (
  history_id  INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  order_id    INTEGER NOT NULL REFERENCES orders(order_id) ON DELETE CASCADE,
  status      order_status NOT NULL,
  changed_by  INTEGER NULL REFERENCES admins(admin_id) ON DELETE SET NULL,
  note        VARCHAR(200),
  changed_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- ------------------------------------------------------------
-- Basket and wishlist (kept server-side so they follow the customer)
-- ------------------------------------------------------------
CREATE TABLE cart_items (
  customer_id INTEGER NOT NULL REFERENCES customers(customer_id) ON DELETE CASCADE,
  product_id  INTEGER NOT NULL REFERENCES products(product_id)   ON DELETE CASCADE,
  quantity    INTEGER NOT NULL DEFAULT 1,
  added_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (customer_id, product_id)
);

CREATE TABLE wishlist_items (
  customer_id INTEGER NOT NULL REFERENCES customers(customer_id) ON DELETE CASCADE,
  product_id  INTEGER NOT NULL REFERENCES products(product_id)   ON DELETE CASCADE,
  added_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (customer_id, product_id)
);

-- ------------------------------------------------------------
-- Behaviour tracking  -->  feeds the Inventory Velocity module
-- ------------------------------------------------------------
-- One row per thing a shopper does. The velocity score weights them:
--   view 1, cart add 3, purchase 5.
CREATE TABLE events (
  event_id    BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  -- NULL = not signed in
  customer_id INTEGER NULL REFERENCES customers(customer_id) ON DELETE SET NULL,
  product_id  INTEGER NOT NULL REFERENCES products(product_id) ON DELETE CASCADE,
  event_type  event_type NOT NULL,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX idx_event_product ON events (product_id, event_type);
CREATE INDEX idx_event_date    ON events (created_at);

-- ------------------------------------------------------------
-- Chatbot transcript, shown in the admin panel
-- ------------------------------------------------------------
CREATE TABLE chatbot_logs (
  log_id            BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  customer_id       INTEGER NULL REFERENCES customers(customer_id) ON DELETE SET NULL,
  question          TEXT NOT NULL,
  answer            TEXT NOT NULL,
  was_build_request SMALLINT NOT NULL DEFAULT 0 CHECK (was_build_request IN (0,1)),
  created_at        TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX idx_log_date ON chatbot_logs (created_at);

-- ------------------------------------------------------------
-- Brute-force protection for the admin sign-in (was 06_login_attempts.sql)
-- ------------------------------------------------------------
CREATE TABLE login_attempts (
  attempt_id   INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  username     VARCHAR(60) NOT NULL,
  ip_address   VARCHAR(45) NOT NULL,   -- 45 chars so an IPv6 address fits
  attempted_at TIMESTAMPTZ NOT NULL
);

-- The lookup is always "failures for this username since <time>",
-- so an index on that pair keeps it fast as the table grows.
CREATE INDEX idx_user_time ON login_attempts (username, attempted_at);
CREATE INDEX idx_ip_time   ON login_attempts (ip_address, attempted_at);

-- ------------------------------------------------------------
-- products.updated_at
--
-- MySQL kept this current with ON UPDATE CURRENT_TIMESTAMP, which the
-- storage engine handled. Postgres has no such column clause, so the
-- same behaviour is a BEFORE UPDATE trigger.
-- ------------------------------------------------------------
CREATE OR REPLACE FUNCTION set_updated_at() RETURNS TRIGGER
LANGUAGE plpgsql
SET search_path = ''
AS $fn$
BEGIN
  NEW.updated_at := now();
  RETURN NEW;
END;
$fn$;

CREATE TRIGGER trg_products_updated_at
  BEFORE UPDATE ON products
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- ------------------------------------------------------------
-- Views used by the dashboard
-- ------------------------------------------------------------

-- Inventory Velocity. This is LFU (least-frequently-used) turned around:
-- instead of finding what to throw away, we rank what customers engage
-- with most. score = views x1 + cart adds x3 + purchases x5
--
-- MySQL could write SUM(e.event_type = 'view') because a comparison
-- there is 1 or 0. Postgres has no such shortcut, so each tally is a
-- COUNT(*) FILTER, which is the same idea spelled out. A product with
-- no activity counts 0 rather than NULL, so untouched stock still sorts
-- properly at the bottom of the ranking — which is exactly what the
-- dead-stock alert needs to find.
CREATE VIEW v_product_velocity AS
SELECT
  p.product_id,
  p.name,
  p.price,
  p.stock_status,
  COUNT(*) FILTER (WHERE e.event_type = 'view')     AS views,
  COUNT(*) FILTER (WHERE e.event_type = 'cart_add') AS cart_adds,
  COUNT(*) FILTER (WHERE e.event_type = 'purchase') AS purchases,
    COUNT(*) FILTER (WHERE e.event_type = 'view')     * 1
  + COUNT(*) FILTER (WHERE e.event_type = 'cart_add') * 3
  + COUNT(*) FILTER (WHERE e.event_type = 'purchase') * 5 AS velocity_score,
  MAX(e.created_at) AS last_activity
FROM products p
LEFT JOIN events e ON e.product_id = p.product_id
WHERE p.is_active = 1
GROUP BY p.product_id, p.name, p.price, p.stock_status;

-- Everything sold, by month, for the sales trend chart.
-- DATE_FORMAT(x, '%Y-%m') becomes to_char(x, 'YYYY-MM').
CREATE VIEW v_monthly_sales AS
SELECT
  to_char(o.order_date, 'YYYY-MM') AS month,
  COUNT(DISTINCT o.order_id)       AS orders,
  SUM(oi.quantity)                 AS units,
  SUM(oi.line_total)               AS revenue
FROM orders o
JOIN order_items oi ON oi.order_id = o.order_id
WHERE o.status <> 'Cancelled'
GROUP BY to_char(o.order_date, 'YYYY-MM');

COMMIT;
